import java.util.concurrent.*
import java.util.concurrent.locks.ReentrantReadWriteLock
import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

data class AuthToken(val userId: String, val roles: Set<String>, val expiresAt: Long, val signature: String)

class TokenCache(private val maxSize: Int = 1000) {
    private val lock = ReentrantReadWriteLock()
    private val cache = LinkedHashMap<String, AuthToken>(maxSize, 0.75f, true)

    fun get(tokenId: String): AuthToken? {
        lock.readLock().lock()
        try {
            return cache[tokenId]
        } finally {
            lock.readLock().unlock()
        }
    }

    fun put(tokenId: String, token: AuthToken) {
        lock.writeLock().lock()
        try {
            if (cache.size >= maxSize) {
                val eldest = cache.entries.iterator().next()
                cache.remove(eldest.key)
            }
            cache[tokenId] = token
        } finally {
            lock.writeLock().unlock()
        }
    }

    fun invalidate(tokenId: String) {
        lock.writeLock().lock()
        try {
            cache.remove(tokenId)
        } finally {
            lock.writeLock().unlock()
        }
    }

    fun isValid(tokenId: String): Boolean {
        lock.readLock().lock()
        try {
            return cache.containsKey(tokenId)
        } finally {
            lock.readLock().unlock()
        }
    }
}

class AuthService(private val secretKey: ByteArray) {
    private val tokenCache = TokenCache()
    private val revokedTokens = ConcurrentHashMap.newKeySet<String>()
    private val validationLock = ReentrantReadWriteLock()

    fun validateAndAuthorize(rawToken: String, requiredRole: String): Boolean {
        val tokenId = computeTokenId(rawToken)

        validationLock.readLock().lock()
        try {
            // Check revocation first under lock
            if (isRevoked(tokenId)) {
                return false
            }

            // Fast path: check cache
            val cached = tokenCache.get(tokenId)
            if (cached != null) {
                return checkAuthorization(cached, requiredRole)
            }
        } finally {
            validationLock.readLock().unlock()
        }

        // Parse and validate the token
        val token = parseToken(rawToken) ?: return false

        // Verify signature
        if (!verifySignature(token, rawToken)) {
            return false
        }

        // Check expiration
        if (token.expiresAt < System.currentTimeMillis()) {
            return false
        }

        // Re-check revocation before caching (under write lock)
        validationLock.writeLock().lock()
        try {
            if (isRevoked(tokenId)) {
                return false
            }
            // Cache the validated token
            tokenCache.put(tokenId, token)
        } finally {
            validationLock.writeLock().unlock()
        }

        return checkAuthorization(token, requiredRole)
    }

    fun revokeToken(rawToken: String) {
        val tokenId = computeTokenId(rawToken)
        validationLock.writeLock().lock()
        try {
            revokedTokens.add(tokenId)
            tokenCache.invalidate(tokenId)
        } finally {
            validationLock.writeLock().unlock()
        }
    }

    private fun isRevoked(tokenId: String): Boolean {
        return revokedTokens.contains(tokenId)
    }

    private fun checkAuthorization(token: AuthToken, requiredRole: String): Boolean {
        if (token.expiresAt < System.currentTimeMillis()) {
            return false
        }
        return token.roles.contains(requiredRole)
    }

    private fun computeTokenId(rawToken: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        // Use the full digest to avoid identifier collisions between distinct tokens.
        return Base64.getUrlEncoder().withoutPadding().encodeToString(digest.digest(rawToken.toByteArray()))
    }

    private fun parseToken(rawToken: String): AuthToken? {
        return try {
            val parts = rawToken.split(".")
            if (parts.size != 3) return null
            val payload = String(Base64.getUrlDecoder().decode(parts[1]))
            val fields = payload.split(",")
            if (fields.size < 3) return null
            AuthToken(
                userId = fields[0],
                roles = fields[1].split(";").toSet(),
                expiresAt = fields[2].toLong(),
                signature = parts[2]
            )
        } catch (e: Exception) {
            null
        }
    }

    private fun verifySignature(token: AuthToken, rawToken: String): Boolean {
        val parts = rawToken.split(".")
        val dataToSign = "${parts[0]}.${parts[1]}"
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(secretKey, "HmacSHA256"))
        val expectedSig = Base64.getUrlEncoder().encodeToString(mac.doFinal(dataToSign.toByteArray()))
        return MessageDigest.isEqual(expectedSig.toByteArray(), token.signature.toByteArray())
    }
}

class ResourceServer(private val authService: AuthService) {
    private val executor = Executors.newFixedThreadPool(8)

    fun handleAdminRequest(rawToken: String, action: String): CompletableFuture<String> {
        return CompletableFuture.supplyAsync({
            if (authService.validateAndAuthorize(rawToken, "admin")) {
                executeAdminAction(action)
            } else {
                "Access Denied"
            }
        }, executor)
    }

    fun handleRevokeAndCheck(rawToken: String, targetToken: String): CompletableFuture<String> {
        return CompletableFuture.supplyAsync({
            authService.revokeToken(targetToken)
            "Token revoked"
        }, executor)
    }

    private fun executeAdminAction(action: String): String {
        return "Executed: $action"
    }
}
